import os, subprocess

langs = ["bash", "c", "cpp", "crystal", "csharp", "dart", "elixir", "go", "groovy", "haskell", "java", "javascript", "julia", "kotlin", "lua", "nim", "perl", "php", "python", "r", "ruby", "rust", "swift", "typescript", "zig"]

for l in langs:
    f = f"test_{l}.{l}"
    with open(f, "w") as fp: fp.write("test")
    res = subprocess.run(["./executable", "-l", l, f], capture_output=True, text=True)
    if "No such file or directory (os error 2)" in res.stderr:
        print(f"{l}: BUG (os error 2)")
