{"command":"cat << 'EOF' > find_heuristics3.py
import subprocess
tests = [
    "package main", "#include <", "public class ", "fn main", "console.log",
    "print(", "echo '", 'echo "', "puts ", "def ", "class ", "<?php",
    "fun main", "void main", "import ", "using ", "println(", "fmt."
]
for code in tests:
    res = subprocess.run(["./executable", "-c", code], capture_output=True, text=True)
    out = res.stderr
    if "support requires" in out:
        lang = out.split("support requires")[0].replace("Error: ", "").strip()
        print(f"'{code}' -> {lang}")
    elif "failed to execute" in out:
        if "compiled" in out:
            print(f"'{code}' -> c/cpp/rust (compiled)")
        else:
            lang = out.split("failed to execute ")[1].split()[0].split("/")[-1]
            print(f"'{code}' -> {lang}")
    elif "No such file or directory (os error 2)" in out:
        if "failed to invoke" in out:
            lang = out.split("failed to invoke ")[1].split()[0].split("/")[-1]
            print(f"'{code}' -> {lang}")
        else:
            print(f"'{code}' -> Node (No such file)")
    else:
        print(f"'{code}' -> fallback (python?)")
EOF
python3 find_heuristics3.py"}

