fn run_group1(input: Input, cmd: &str, code_args: &[&str], no_path_err: Option<&str>) {
    if let Some(err_msg) = no_path_err {
        if resolve_binary(cmd).is_none() {
            eprintln!("{}", err_msg);
            std::process::exit(1);
        }
    }
    let mut command = Command::new(cmd);
    match &input {
        Input::Code(c) => {
            for a in code_args { command.arg(a); }
            command.arg(c);
        },
        Input::File(p) => {
            command.arg(p);
        }
    }
    if let Err(e) = command.status() {
        if cmd == "bash" {
        } else {
            eprintln!("Error: {}", e);
        }
        std::process::exit(1);
    }
}

fn run_bash(input: Input) { run_group1(input, "bash", &["-c"], None); }
fn run_python(input: Input) { run_group1(input, "python3", &["-c"], None); }
fn run_javascript(input: Input) { run_group1(input, "node", &["-e"], None); }
fn run_ruby(input: Input) { run_group1(input, "ruby", &["-e"], None); }
fn run_groovy(input: Input) { run_group1(input, "groovy", &["-e"], Some("Error: Groovy support requires the `groovy` executable. Install it from https://groovy-lang.org/download.html and make sure it is available on your PATH.")); }

fn run_r(input: Input) {
    if resolve_binary("Rscript").is_none() {
        eprintln!("Error: R support requires the `Rscript` executable. Install R from https://cran.r-project.org/ and ensure `Rscript` is on your PATH.");
        std::process::exit(1);
    }
    match input {
        Input::Code(c) => {
            let temp_dir = env::temp_dir().join(format!("run-r{}", random_string()));
            fs::create_dir_all(&temp_dir).unwrap();
            let file_path = temp_dir.join("snippet.R");
            fs::write(&file_path, format!("{}\n", c)).unwrap();
            Command::new("Rscript").args(["--vanilla", file_path.to_str().unwrap()]).status().unwrap();
        },
        Input::File(p) => {
            Command::new("Rscript").args(["--vanilla", &p]).status().unwrap();
        }
    }
}

fn run_typescript(input: Input) {
    if resolve_binary("deno").is_none() {
        if let Input::Code(_) = input {
            eprintln!("Error: failed to run Deno for inline execution because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH.");
        } else {
            eprintln!("Error: failed to run Deno for file execution because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH.");
        }
        std::process::exit(1);
    }
    let mut command = Command::new("deno");
    command.args(["run", "--quiet", "--no-check", "--ext", "ts"]);
    match input {
        Input::Code(c) => {
            let temp_file = env::temp_dir().join(format!(".tmp{}", random_string()));
            fs::write(&temp_file, c).unwrap();
            command.arg(&temp_file);
            let _ = command.status();
        },
        Input::File(p) => {
            command.arg(p);
            let _ = command.status();
        }
    }
}

fn run_group3(input: Input, lang_name: &str, cmd: &str, args: &[&str], snippet_name: &str, no_path_err: &str) {
    let full_path = if let Some(p) = resolve_binary(cmd) { p } else {
        eprintln!("{}", no_path_err);
        std::process::exit(1);
    };
    let temp_dir = env::temp_dir().join(format!("run-{}{}", lang_name, random_string()));
    let mut command = Command::new(&full_path);
    for a in args { command.arg(a); }
    match &input {
        Input::Code(c) => {
            fs::create_dir_all(&temp_dir).unwrap();
            let file_path = temp_dir.join(snippet_name);
            let content = if lang_name == "php" { format!("<?php\n{}\n", c) } 
                          else if lang_name == "dart" { format!("Future<void> main() async {{\n  {};\n}}\n", c) }
                          else if lang_name == "zig" { format!("const std = @import(\"std\");\n\npub fn main() !void {{\n    {}\n}}\n", c) }
                          else { format!("{}\n", c) };
            fs::write(&file_path, content).unwrap();
            if lang_name == "go" || lang_name == "dart" { command.arg(snippet_name); } 
            else if lang_name == "crystal" { command.arg(&file_path); command.arg("--no-color"); } 
            else { command.arg(&file_path); }
            command.current_dir(&temp_dir);
        },
        Input::File(path) => {
            if lang_name == "go" || lang_name == "dart" { command.arg(Path::new(&path).file_name().unwrap()); } 
            else if lang_name == "crystal" { command.arg(&path); command.arg("--no-color"); } 
            else { command.arg(&path); }
            if let Some(p) = Path::new(&path).parent() {
                if p.to_string_lossy() == "" {
                    command.current_dir("");
                } else {
                    command.current_dir(p);
                }
            }
        }
    }
    if let Err(_e) = command.spawn() {
        let arg = match &input { Input::Code(_) => snippet_name.to_string(), Input::File(p) => p.to_string() };
        eprintln!("Error: failed to invoke {} to run {}", full_path.display(), arg);
        eprintln!("\nCaused by:\n    No such file or directory (os error 2)");
        std::process::exit(1);
    } else {
        let _ = command.status();
    }
}
