fn run_group3(input: Input, lang_name: &str, cmd: &str, args: &[&str], snippet_name: &str, no_path_err: &str) {
    let full_path = if let Some(p) = resolve_binary(cmd) { p } else {
        eprintln!("{}", no_path_err);
        std::process::exit(1);
    };
    let temp_dir = env::temp_dir().join(format!("run-{}{}", lang_name, random_string()));
    let mut command = Command::new(&full_path);
    for a in args { command.arg(a); }
    match &input {
        Input::Code(c) => {
            fs::create_dir_all(&temp_dir).unwrap();
            let file_path = temp_dir.join(snippet_name);
            let content = if lang_name == "php" { format!("<?php\n{}\n", c) } 
                          else if lang_name == "dart" { format!("Future<void> main() async {{\n  {};\n}}\n", c) }
                          else if lang_name == "zig" { format!("const std = @import(\"std\");\n\npub fn main() !void {{\n    {}\n}}\n", c) }
                          else { format!("{}\n", c) };
            fs::write(&file_path, content).unwrap();
            if lang_name == "go" || lang_name == "dart" { command.arg(snippet_name); } 
            else if lang_name == "crystal" { command.arg(&file_path); command.arg("--no-color"); } 
            else { command.arg(&file_path); }
            command.current_dir(&temp_dir);
        },
        Input::File(path) => {
            if lang_name == "go" || lang_name == "dart" { command.arg(Path::new(&path).file_name().unwrap()); } 
            else if lang_name == "crystal" { command.arg(&path); command.arg("--no-color"); } 
            else { command.arg(&path); }
            if let Some(p) = Path::new(&path).parent() {
                if p.to_string_lossy() == "" {
                    command.current_dir("");
                } else {
                    command.current_dir(p);
                }
            }
        }
    }
    if let Err(_e) = command.spawn() {
        let arg = match &input { Input::Code(_) => snippet_name.to_string(), Input::File(p) => p.to_string() };
        eprintln!("Error: failed to invoke {} to run {}", full_path.display(), arg);
        eprintln!("\nCaused by:\n    No such file or directory (os error 2)");
        std::process::exit(1);
    } else {
        let _ = command.status();
    }
}
EOF"}

