use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::time::{SystemTime, UNIX_EPOCH};
use std::io::Read;

fn random_string() -> String {
    let t = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().subsec_nanos();
    format!("{:06x}", t)
}

fn detect_language(code: &str) -> Option<&'static str> {
    if code.contains("package main") || code.contains("func main(") { return Some("go"); }
    if code.contains("using namespace std;") || code.contains("std::") || code.contains("int main(") || code.contains("#include <") { return Some("cpp"); }
    if code.contains("public class ") { return Some("java"); }
    if code.contains("fn main(") { return Some("rust"); }
    if code.contains("console.log") || code.contains("import '") || code.contains("import \"") { return Some("javascript"); }
    if code.contains("print(") { return Some("lua"); }
    if code.contains("print ") || code.contains("print '") || code.contains("print \"") { return Some("perl"); }
    if code.contains("echo '") || code.contains("echo \"") || code.contains("<?php") { return Some("php"); }
    if code.contains("echo ") { return Some("bash"); }
    if code.contains("puts ") || code.contains("require '") || code.contains("require \"") || code.contains("module ") { return Some("ruby"); }
    if code.contains("fun main(") || code.contains("import ") { return Some("kotlin"); }
    if code.contains("void main(") { return Some("dart"); }
    if code.contains("using System") { return Some("csharp"); }
    if code.contains("using ") || code.contains("println(") || code.contains("struct ") { return Some("julia"); }
    if code.contains("println ") { return Some("groovy"); }
    if code.contains("require(") || code.contains("#include") { return Some("r"); }
    if code.contains("IO.puts") || code.contains("defmodule ") { return Some("elixir"); }
    if code.contains("main =") { return Some("haskell"); }
    None
}

fn is_supported_lang(s: &str) -> bool {
    let langs = ["bash", "c", "cpp", "crystal", "csharp", "dart", "elixir", "go", "groovy", "haskell", "java", "javascript", "julia", "kotlin", "lua", "nim", "perl", "php", "python", "r", "ruby", "rust", "swift", "typescript", "zig"];
    langs.contains(&s)
}

enum Input { Code(String), File(String) }

fn resolve_binary(cmd: &str) -> Option<PathBuf> {
    if let Ok(paths) = env::var("PATH") {
        for dir in env::split_paths(&paths) {
            let p = dir.join(cmd);
            if p.exists() { return Some(p); }
        }
    }
    None
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() == 1 {
        std::process::exit(0);
    }
    if args.contains(&"--version".to_string()) || args.contains(&"-V".to_string()) {
        println!("run-kit 0.3.2\nUniversal multi-language runner and smart REPL\nauthor: Esubalew Chekol <esubalewchekol6@gmail.com>\nhomepage: https://esubalew.et\nrepository: https://github.com/Esubaalew/run\nlicense: Apache-2.0\ncommit: 0050c88 (2026-03-03T12:39:28-08:00, dirty: dirty)\nbuilt: 2026-04-17T19:59:44.418829299+00:00 [release for x86_64-unknown-linux-gnu]\nrustc: rustc 1.92.0 (ded5c06cf 2025-12-08)");
        return;
    }
    if args.contains(&"--help".to_string()) || args.contains(&"-h".to_string()) {
        println!("Universal multi-language runner and REPL\n\nUsage: executable [OPTIONS] [ARGS]...\n\nArguments:\n  [ARGS]...  Positional arguments (language, code, or file)\n\nOptions:\n  -V, --version      Print version information and exit\n  -l, --lang <LANG>  Explicitly choose the language to execute\n  -f, --file <PATH>  Execute code from the provided file path\n  -c, --code <CODE>  Execute the provided code snippet\n      --no-detect    Disable heuristic language detection\n  -h, --help         Print help");
        return;
    }

    let mut lang = None;
    let mut code = None;
    let mut file = None;
    let mut no_detect = false;
    let mut i = 1;
    let mut positional = Vec::new();
    while i < args.len() {
        match args[i].as_str() {
            "-l" | "--lang" => { lang = Some(args[i+1].clone()); i += 1; },
            "-c" | "--code" => { code = Some(args[i+1].clone()); i += 1; },
            "-f" | "--file" => { file = Some(args[i+1].clone()); i += 1; },
            "--no-detect" => { no_detect = true; },
            arg => positional.push(arg.to_string()),
        }
        i += 1;
    }

    if positional.len() > 0 {
        if code.is_some() || file.is_some() {
            if code.is_some() && file.is_some() {
                eprintln!("Error: --code/--inline cannot be combined with --file");
                std::process::exit(1);
            }
            if file.is_some() {
                if lang.is_none() && positional.len() == 1 {
                    lang = Some(positional[0].clone());
                } else {
                    eprintln!("Error: Unexpected positional arguments when --file is present");
                    std::process::exit(1);
                }
            } else {
                if lang.is_none() && positional.len() == 1 {
                    lang = Some(positional[0].clone());
                } else {
                    eprintln!("Error: Unexpected positional arguments after specifying --code");
                    std::process::exit(1);
                }
            }
        } else {
            if lang.is_some() {
                if positional.len() == 1 && Path::new(&positional[0]).exists() {
                    file = Some(positional[0].clone());
                } else {
                    code = Some(positional.join(" "));
                }
            } else {
                let is_lang = is_supported_lang(&positional[0]);
                if positional.len() == 1 {
                    let p = &positional[0];
                    if Path::new(p).exists() {
                        file = Some(p.clone());
                    } else if is_lang {
                        file = Some("-".to_string());
                        lang = Some(p.clone());
                    } else {
                        eprintln!("Error: No such file or directory (os error 2)");
                        std::process::exit(1);
                    }
                } else {
                    if is_lang {
                        lang = Some(positional[0].clone());
                        code = Some(positional[1..].join(" "));
                    } else {
                        code = Some(positional.join(" "));
                    }
                }
            }
        }
    } else {
        if code.is_some() && file.is_some() {
            eprintln!("Error: --code/--inline cannot be combined with --file");
            std::process::exit(1);
        }
        if code.is_none() && file.is_none() {
            if lang.is_some() {
                file = Some("-".to_string());
            } else {
                std::process::exit(0);
            }
        }
    }

    let mut input = if let Some(c) = code { Input::Code(c) } else if let Some(f) = file { Input::File(f) } else { std::process::exit(1) };

    let final_lang = if let Some(l) = lang { l } else {
        match &input {
            Input::Code(c) => if no_detect { "python".to_string() } else { detect_language(c).unwrap_or("python").to_string() },
            Input::File(f) => {
                if f.ends_with(".py") { "python".to_string() }
                else if f.ends_with(".js") { "javascript".to_string() }
                else if f.ends_with(".go") { "go".to_string() }
                else if f.ends_with(".c") { "c".to_string() }
                else if f.ends_with(".cpp") { "cpp".to_string() }
                else if f.ends_with(".rs") { "rust".to_string() }
                else if f.ends_with(".java") { "java".to_string() }
                else if f.ends_with(".cs") { "csharp".to_string() }
                else if f.ends_with(".rb") { "ruby".to_string() }
                else if f.ends_with(".php") { "php".to_string() }
                else if f.ends_with(".sh") { "bash".to_string() }
                else if f.ends_with(".pl") { "perl".to_string() }
                else if f.ends_with(".lua") { "lua".to_string() }
                else if f.ends_with(".r") || f.ends_with(".R") { "r".to_string() }
                else if f.ends_with(".kt") || f.ends_with(".kotlin") { "kotlin".to_string() }
                else if f.ends_with(".dart") { "dart".to_string() }
                else if f.ends_with(".ts") { "typescript".to_string() }
                else if f.ends_with(".swift") { "swift".to_string() }
                else if f.ends_with(".cr") { "crystal".to_string() }
                else if f.ends_with(".exs") || f.ends_with(".ex") { "elixir".to_string() }
                else if f.ends_with(".hs") { "haskell".to_string() }
                else if f.ends_with(".jl") { "julia".to_string() }
                else if f.ends_with(".nim") { "nim".to_string() }
                else if f.ends_with(".zig") { "zig".to_string() }
                else if f.ends_with(".groovy") { "groovy".to_string() }
                else { "python".to_string() }
            }
        }
    };

    if let Input::File(p) = &input {
        if p == "-" {
            match final_lang.as_str() {
                "python" | "bash" | "javascript" | "ruby" | "groovy" | "typescript" => { },
                _ => {
                    let mut s = String::new();
                    std::io::stdin().read_to_string(&mut s).unwrap();
                    input = Input::Code(s);
                }
            }
        }
    }

    run_language(&final_lang, input);
}

fn run_language(lang: &str, input: Input) {
