    if code.contains("print ") || code.contains("print '") || code.contains("print \"") { return Some("perl"); }
    if code.contains("echo '") || code.contains("echo \"") || code.contains("<?php") { return Some("php"); }
    if code.contains("echo ") { return Some("bash"); }
    if code.contains("puts ") || code.contains("require '") || code.contains("require \"") || code.contains("module ") { return Some("ruby"); }
    if code.contains("fun main(") || code.contains("import ") { return Some("kotlin"); }
