fn run_java(input: Input) {
    if resolve_binary("javac").is_none() {
        eprintln!("Error: Java support requires the `javac` compiler. Install the JDK from https://adoptium.net/ or your vendor of choice and ensure it is on your PATH.");
        std::process::exit(1);
    }
    let temp_dir = env::temp_dir().join(format!("run-java{}", random_string()));
    fs::create_dir_all(&temp_dir).unwrap();
    let (file_name, class_name) = match input {
        Input::Code(c) => {
            let f = temp_dir.join("Main.java");
            fs::write(&f, format!("public class Main {{\n    public static void main(String[] args) throws Exception {{\n        {}\n    }}\n}}\n", c)).unwrap();
            (f.to_string_lossy().into_owned(), "Main".to_string())
        },
        Input::File(p) => {
            let name = Path::new(&p).file_name().unwrap().to_string_lossy().into_owned();
            let f = temp_dir.join(&name);
            fs::copy(&p, &f).unwrap();
            let c = name.strip_suffix(".java").unwrap_or(&name).to_string();
            (f.to_string_lossy().into_owned(), c)
        }
    };
    if Command::new("javac").args(["-d", temp_dir.to_str().unwrap(), &file_name]).status().unwrap().success() {
        Command::new("java").args(["-cp", temp_dir.to_str().unwrap(), &class_name]).status().unwrap();
    }
}

